/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class FingerprintRulesUnitTest {

  private static final String STACK = "java.lang.IllegalStateException: boom\n"
      + "\tat com.acme.retry.Retrier.call(Retrier.java:10)\n"
      + "\tat com.acme.orders.OrderService.find(OrderService.java:20)";

  private static ErrorEvent event(final String message) {
    return new ErrorEvent("api", 1L, "ERROR", "java.lang.IllegalStateException", message, STACK,
        null, null, null, null);
  }

  private static FingerprintRules.Rule rule(final String origin, final String field,
      final String pattern, final String effect, final String key) {
    return new FingerprintRules.Rule("r-" + effect, origin, field,
        SafeRegex.compile(pattern).orElseThrow(), effect, key);
  }

  @Test
  @DisplayName("drop: no issue; group-as: the same fingerprint for different errors; only in its origin")
  void dropAndGroup() {
    List<FingerprintRules.Rule> rules =
        List.of(rule(null, "message", "ResizeObserver", "drop", null),
            rule("o1", "message", "timeout", "group-as", "timeouts"));
    Assertions
        .assertTrue(FingerprintRules.apply(rules, "o1", event("ResizeObserver loop limit")).drop());
    ErrorEvent a = FingerprintRules.apply(rules, "o1", event("timeout calling payments")).event();
    ErrorEvent b = FingerprintRules.apply(rules, "o1", event("timeout reading stock")).event();
    Assertions.assertNotNull(a.fingerprint());
    Assertions.assertEquals(a.fingerprint(), b.fingerprint());
    Assertions.assertNull(FingerprintRules.apply(rules, "o2", event("timeout calling payments"))
        .event().fingerprint());
  }

  @Test
  @DisplayName("ignore-frame: the wrapper does not count in the fingerprint")
  void ignoreFrame() {
    List<FingerprintRules.Rule> rules =
        List.of(rule(null, "frame", "Retrier", "ignore-frame", null));
    FingerprintRules.Decision decision = FingerprintRules.apply(rules, "o1", event("boom"));
    Assertions.assertEquals(List.of("com.acme.orders.OrderService.find"),
        IssueFingerprint.frames(STACK, List.of("com.acme."), decision.ignoreFrame()));
  }

  @Test
  @DisplayName("Too long, invalid or catastrophic expressions never block")
  void safety() {
    Assertions.assertTrue(SafeRegex.compile("a".repeat(SafeRegex.MAX_LENGTH + 1)).isEmpty());
    Assertions.assertTrue(SafeRegex.compile("(unclosed").isEmpty());
    long start = System.nanoTime();
    Assertions.assertFalse(
        SafeRegex.find(SafeRegex.compile("(a+)+$").orElseThrow(), "a".repeat(40) + "!"));
    Assertions.assertTrue((System.nanoTime() - start) / 1_000_000 < 2_000);
  }
}
